(function(){if(!window.isSecureContext||!navigator.clipboard)return;Array.prototype.forEach.call(document.querySelectorAll("button.copy"),function(e){var n=document.getElementById(e.getAttribute("data-copy-target")),t=e.nextElementSibling;if(!n||!t||!t.classList.contains("copy-status"))return;e.hidden=!1,e.addEventListener("click",function(){navigator.clipboard.writeText(n.textContent).then(function(){t.textContent=e.getAttribute("data-copy-done")},function(){t.textContent=e.getAttribute("data-copy-failed")})})})})()